.jet-listing-grid__item:nth-child(4n) .p_con {
    border-left: none;
}
@media (max-width: 767px) {
    /* Add left border to all .p_con */
    .jet-listing-grid__item .p_con {
        border-left: 1px solid #ddd; /* adjust as needed */
    }

    /* Remove border from the first item */
    .jet-listing-grid__item:first-child .p_con {
        border-left: none;
    }

    /* Remove border from the last item */
    .jet-listing-grid__item:last-child .p_con {
        border-left: none;
    }
